  $typ1json${"slug": "typography-i", "title": "Typography I", "description": "Typography I treats typography as a system for making language visible, expressive, organized, and useful. Students study letterform anatomy, classification and history, type families and selection, spacing and rhythm, hierarchy, grids, composition, legibility, voice, editorial typesetting, screen and responsive type, inclusive practice, specimens, critique, and a final typographic system.", "topics": [{"id": "bc5a3f60-83b0-4ecd-a821-535fb9e3c263", "type": "topic", "title": "Typography as Visual Language", "description": "Understand typography as a system for making language visible, expressive, organized, and useful.", "children": [{"id": "dfe2a63b-8171-413f-b153-2387afa28b72", "type": "subtopic", "title": "Visible language", "children": [{"id": "6e9bbb2d-462e-4254-b09d-cdeff073b530", "type": "concept", "title": "Form and meaning"}, {"id": "74bf9515-f4d7-4882-bab6-52599499f7ce", "type": "concept", "title": "Tone and connotation"}, {"id": "582d8691-9ecb-46d5-88c2-eeb991107eb9", "type": "concept", "title": "Type as image"}, {"id": "0d9046b8-16b7-4b22-b07c-4f6b93740a2b", "type": "concept", "title": "Type as interface"}], "description": "Gist: Typography begins with the idea that words have visual form before they are read as language."}, {"id": "f23ffcfb-d23f-4166-97dc-7fb215e2cb90", "type": "subtopic", "title": "Typographic responsibility", "children": [{"id": "b2e2f6c5-6bb2-4a8d-8557-aae3c8b15a50", "type": "concept", "title": "Reader needs"}, {"id": "1705f85a-977b-412b-9595-2cdacfdc575a", "type": "concept", "title": "Context of use"}, {"id": "7acb765e-6c28-4367-a74b-5fad65895402", "type": "concept", "title": "Authority and credibility"}, {"id": "0d77058e-cef8-4294-acc1-893d9c2a3e86", "type": "concept", "title": "Ethical presentation"}], "description": "Gist: Designers make choices that affect comprehension, trust, access, and cultural meaning."}, {"id": "74aad7e8-79bc-4d7b-bbd0-c918e2a3046e", "type": "subtopic", "title": "Studio habits for type", "children": [{"id": "400cd256-ed77-4221-9db3-6f9db23ca41b", "type": "concept", "title": "Type sketchbook"}, {"id": "6231c806-4e21-4525-b6ca-b8544e1f6469", "type": "concept", "title": "Specimen collection"}, {"id": "fae6888d-96e8-4359-8ae8-ea43de8af405", "type": "concept", "title": "Daily type observations"}, {"id": "fe3fc94a-32d9-41de-af61-46d9cfb94933", "type": "concept", "title": "Before-and-after studies"}], "description": "Gist: Typography improves through close looking, comparison, testing, and revision."}]}, {"id": "9838463c-ecbf-49f4-998b-f3239d12b89a", "type": "topic", "title": "Letterforms and Anatomy", "description": "Learn the parts, proportions, and construction logic of letters so type can be seen precisely.", "children": [{"id": "6130475c-896d-47cf-91a2-8cc2784f34cb", "type": "subtopic", "title": "Anatomical vocabulary", "children": [{"id": "225239ac-191f-4391-80f1-cd739965b649", "type": "concept", "title": "Baseline"}, {"id": "2c8dbc96-5cbb-49f4-91da-589b253c7f02", "type": "concept", "title": "X-height"}, {"id": "ce209831-eb81-4e41-952c-50ef79dc51a1", "type": "concept", "title": "Ascenders and descenders"}, {"id": "132257df-5618-429b-8f9b-9b14ec1863ef", "type": "concept", "title": "Counters and apertures"}], "description": "Gist: Letter anatomy gives students precise language for comparing typefaces and diagnosing problems."}, {"id": "0fc11c50-8874-4390-a812-eb8968c0f1e9", "type": "subtopic", "title": "Proportion and construction", "children": [{"id": "449cc123-738d-4723-a60f-209c0f2d37d5", "type": "concept", "title": "Stem and stroke"}, {"id": "48b8f42a-174a-49f5-bcee-c373be19051d", "type": "concept", "title": "Serif and terminal"}, {"id": "38e814dd-6cae-4417-a4f7-a19a1c13c2f1", "type": "concept", "title": "Bowl and shoulder"}, {"id": "1ac0c463-a012-4fc4-9380-2ae9ab10146d", "type": "concept", "title": "Optical correction"}], "description": "Gist: Letters are built from relationships of width, weight, curve, stress, and spacing."}, {"id": "2e3e9e85-a74e-4a68-8d54-5ee5a2434438", "type": "subtopic", "title": "Drawing and close observation", "children": [{"id": "ccbdba4e-7fde-49c4-9edf-ac1983e042e9", "type": "concept", "title": "Tracing studies"}, {"id": "3745d7fd-5353-4643-b3b5-390dad0efeb5", "type": "concept", "title": "Counterform studies"}, {"id": "b681ab31-8001-4318-9d51-91adc936babd", "type": "concept", "title": "Curve-to-straight transitions"}, {"id": "82b43fd2-e480-4145-8628-9ff6ecabf21d", "type": "concept", "title": "Letter pair studies"}], "description": "Gist: Drawing letters by hand trains the eye to notice details hidden by casual font browsing."}]}, {"id": "887e9dcd-3ee9-4b6b-851a-6ed062172610", "type": "topic", "title": "Type Classification and History", "description": "Connect type styles to historical, technological, and cultural contexts rather than treating fonts as neutral decoration.", "children": [{"id": "bb7f112f-5a24-420c-9779-ca6c8d3973fd", "type": "subtopic", "title": "Classification systems", "children": [{"id": "55281c7b-35ec-4242-8764-fefde108ad2b", "type": "concept", "title": "Oldstyle"}, {"id": "a63edccf-2ad4-4811-8dc8-d10b2430985a", "type": "concept", "title": "Transitional"}, {"id": "8edd45fb-b3c4-4fe3-a92e-805747ea1880", "type": "concept", "title": "Modern"}, {"id": "ad698dc0-bd80-4805-bc66-191702bd8955", "type": "concept", "title": "Slab serif and sans serif"}], "description": "Gist: Classification helps designers locate typefaces within broad traditions and likely uses."}, {"id": "a9135cd3-4113-457c-af91-b84b4fcb2448", "type": "subtopic", "title": "Technology and type history", "children": [{"id": "54a99874-a319-4ad6-92e0-e21e449fa2ee", "type": "concept", "title": "Manuscript origins"}, {"id": "20ef12df-c5ca-415a-8c7a-1239a984dab1", "type": "concept", "title": "Movable type"}, {"id": "7ab22314-8046-4974-ae15-5fefb3948b03", "type": "concept", "title": "Industrial display type"}, {"id": "dc9f6590-75ae-443b-91a9-da6e8283bca8", "type": "concept", "title": "Digital type"}], "description": "Gist: Typographic form changes with writing tools, printing technologies, screens, and production systems."}, {"id": "55bc3752-564f-4997-b986-e7659af66487", "type": "subtopic", "title": "Cultural context", "children": [{"id": "b1c9d83a-4f48-46d1-8efa-5ffd4afdc6fb", "type": "concept", "title": "National traditions"}, {"id": "e10305dc-2490-470b-a504-e9fb0bc99d3f", "type": "concept", "title": "Modernism"}, {"id": "88547021-c153-43dc-9734-0ac16f08f6c6", "type": "concept", "title": "Postmodern typography"}, {"id": "8e2fdb60-9f76-473c-9455-0feed9e29a34", "type": "concept", "title": "Vernacular type"}], "description": "Gist: Type carries associations shaped by geography, institutions, commerce, and visual culture."}]}, {"id": "6ef8e029-c8cd-47a8-a0e1-454faa765cb9", "type": "topic", "title": "Type Families, Fonts, and Selection", "description": "Build judgment around choosing typefaces for purpose, audience, medium, tone, and functional constraints.", "children": [{"id": "7b633efa-7201-40ea-8bf3-581198db27ca", "type": "subtopic", "title": "Typeface families", "children": [{"id": "896c9503-a17b-422e-916a-bee46eb22f4a", "type": "concept", "title": "Weights"}, {"id": "17ac9fbb-f2b1-40f3-9896-e6c3b7680dda", "type": "concept", "title": "Widths"}, {"id": "9d1961c2-4cbf-4b8a-8354-77288ee159bd", "type": "concept", "title": "Italics"}, {"id": "516778ab-45c9-42c5-ac8d-a0be365ef1db", "type": "concept", "title": "Optical sizes"}], "description": "Gist: Families provide systematic variation that supports hierarchy and consistency."}, {"id": "0969adb1-5ce9-4f78-8870-55debb7a7f55", "type": "subtopic", "title": "Selection criteria", "children": [{"id": "8135eaff-dea2-4251-b0fb-9e5056a030c4", "type": "concept", "title": "Audience"}, {"id": "0a9ea237-0f8c-4cba-8aaf-96295cfed84d", "type": "concept", "title": "Medium"}, {"id": "96ff91c0-3855-41cd-a37f-4d93a1380ccf", "type": "concept", "title": "Content genre"}, {"id": "83358e2e-d393-439e-8b9c-14793c40c100", "type": "concept", "title": "Licensing and availability"}], "description": "Gist: Strong type choice starts from the problem, not from personal taste alone."}, {"id": "e1563e35-b830-465f-b1ce-e54b95534682", "type": "subtopic", "title": "Pairing typefaces", "children": [{"id": "c32fa354-9ac0-44c4-8c81-f9fd9025b129", "type": "concept", "title": "Serif and sans pairing"}, {"id": "272653fe-7477-4c73-8c53-8322dc538a9c", "type": "concept", "title": "Display plus text"}, {"id": "72c892f8-447e-4793-b7a5-4088d7353958", "type": "concept", "title": "Superfamilies"}, {"id": "e5ca4a44-86fa-4b41-b508-cc7da07a5303", "type": "concept", "title": "Avoiding conflict"}], "description": "Gist: Pairing requires contrast, compatibility, and a clear division of labor."}]}, {"id": "837e6ded-efdb-4dca-87bc-d8187d731c00", "type": "topic", "title": "Spacing: Kerning, Tracking, Leading, and Rhythm", "description": "Control the micro-decisions that determine whether type feels careful, readable, and professional.", "children": [{"id": "8b7321b7-5808-498d-bbd3-bbd6d5f53f5d", "type": "subtopic", "title": "Kerning and letterspacing", "children": [{"id": "6039e9a2-820e-4cdb-a5d0-d4f9d687549c", "type": "concept", "title": "Problem pairs"}, {"id": "50adc9bb-8bdd-4799-998d-adc3a4fbb06a", "type": "concept", "title": "Optical spacing"}, {"id": "3152f705-629b-4db4-b195-902d0bc52877", "type": "concept", "title": "All caps tracking"}, {"id": "c0bed34a-d47c-4ef4-bc9c-9f6ffed7b77d", "type": "concept", "title": "Display spacing"}], "description": "Gist: Micro-spacing makes words look even and intentional instead of mechanically assembled."}, {"id": "c39c2c24-f185-497e-98bb-e2a58ae5d15d", "type": "subtopic", "title": "Leading and line length", "children": [{"id": "e4e53560-277b-44bd-8f2e-14bc01035b37", "type": "concept", "title": "Measure"}, {"id": "de0c3e48-2487-4d25-addb-ac9f8f619ede", "type": "concept", "title": "Line height"}, {"id": "91d680a8-444e-47d5-9488-9604514f7ac1", "type": "concept", "title": "Rag quality"}, {"id": "ef8fef42-708f-4731-a47a-162970d28250", "type": "concept", "title": "Paragraph density"}], "description": "Gist: Line spacing and measure shape reading comfort, pace, and typographic color."}, {"id": "ae693691-fa69-4612-87f0-2b4b61f7ef2d", "type": "subtopic", "title": "Rhythm and typographic color", "children": [{"id": "64fb4da5-837c-4e4f-8a20-1fd01c772f36", "type": "concept", "title": "Even texture"}, {"id": "9657c86a-a76e-48a4-b70e-f8ff56da3100", "type": "concept", "title": "White space"}, {"id": "298f8567-c941-4b33-aae7-154d5ceefd99", "type": "concept", "title": "Vertical rhythm"}, {"id": "f8949d68-7e1e-41a5-ba31-60794f26378f", "type": "concept", "title": "Spacing hierarchy"}], "description": "Gist: Spacing creates the overall texture of a page or screen."}]}, {"id": "c2dcde88-b044-4ea3-893c-522e98e93aa9", "type": "topic", "title": "Hierarchy and Information Structure", "description": "Use typographic contrast to guide attention, clarify meaning, and organize complex information.", "children": [{"id": "de4d3d28-3842-4d23-b1ac-a87bda4ea048", "type": "subtopic", "title": "Contrast tools", "children": [{"id": "77c970c9-b19a-4673-818d-2fc4856b980f", "type": "concept", "title": "Size"}, {"id": "6040154b-eeca-469c-b69f-51b32e39870d", "type": "concept", "title": "Weight"}, {"id": "ea80ae49-bd98-47c3-a4ba-2dfefb17790e", "type": "concept", "title": "Color"}, {"id": "f94a2b7d-8601-4bbd-b91e-da8a2986fff9", "type": "concept", "title": "Position and spacing"}], "description": "Gist: Hierarchy is created through controlled differences that tell readers what to see first."}, {"id": "ee24a06c-0c4e-455b-8578-51fb4a69e32f", "type": "subtopic", "title": "Information chunking", "children": [{"id": "a4212b0b-7727-4510-92a3-db56ddb062f3", "type": "concept", "title": "Headings"}, {"id": "dba060c4-a047-4b67-8f99-3c0ccc6398fb", "type": "concept", "title": "Subheads"}, {"id": "48cfed3a-a116-48e0-90a3-519b3c93f180", "type": "concept", "title": "Captions"}, {"id": "2fddba5a-06a2-4c54-8c0c-46a02043f355", "type": "concept", "title": "Pull quotes and side notes"}], "description": "Gist: Typography organizes content into scanable units and relationships."}, {"id": "e4161698-ebd1-41bf-a4d1-372b0f767a90", "type": "subtopic", "title": "Reading paths", "children": [{"id": "75b0015f-19d8-43f0-b904-6a98c9a943d9", "type": "concept", "title": "Entry points"}, {"id": "e4d712f2-1550-423a-809a-666a64f91bec", "type": "concept", "title": "Primary and secondary reads"}, {"id": "1038f04b-e577-42ba-ace7-2f3beddaa7e6", "type": "concept", "title": "Emphasis without clutter"}, {"id": "8e806827-ebaa-430f-8e04-f03134999587", "type": "concept", "title": "Sequence"}], "description": "Gist: Good hierarchy creates a deliberate path through information."}]}, {"id": "0d0e02b6-057f-48de-b328-bd2459e537aa", "type": "topic", "title": "Grids, Alignment, and Layout Systems", "description": "Develop page and screen structures that support rhythm, consistency, and visual order.", "children": [{"id": "1e4a2d9f-f53c-4d23-8767-278984935055", "type": "subtopic", "title": "Grid fundamentals", "children": [{"id": "65d63e96-4488-4287-a21b-2a1fe395a12a", "type": "concept", "title": "Margins"}, {"id": "1ef04f6e-b2fa-44da-8473-55709aea2ed2", "type": "concept", "title": "Columns"}, {"id": "3b4cfe6c-4953-4f7c-83a0-ae3d3ae17d00", "type": "concept", "title": "Gutters"}, {"id": "fc9e762e-3910-4fc4-8489-d61519563723", "type": "concept", "title": "Modules"}], "description": "Gist: Grids create a hidden structure that supports consistency, variation, and efficient decision-making."}, {"id": "2a1272ce-87ec-4d5b-9338-50bfca76faad", "type": "subtopic", "title": "Alignment and proximity", "children": [{"id": "3bbebe90-a4be-4e0b-baef-23d0fe13489c", "type": "concept", "title": "Left, centered, and justified alignment"}, {"id": "0e6e06f3-2dbb-46b2-9439-cc913a506a09", "type": "concept", "title": "Optical alignment"}, {"id": "efd4d6ec-ee1e-496b-b39d-2c266bc0faa3", "type": "concept", "title": "Grouping"}, {"id": "fe62130d-ee63-4204-b6f8-1d048280da5f", "type": "concept", "title": "Baseline relationships"}], "description": "Gist: Alignment clarifies relationships and makes layouts feel intentional."}, {"id": "29bcb738-471f-4969-8477-72ad0b402a06", "type": "subtopic", "title": "System flexibility", "children": [{"id": "7ce05d57-91b9-46ae-9865-b3af5717dfc0", "type": "concept", "title": "Breaking the grid"}, {"id": "6ae50b84-71cf-4baf-b94c-bae3b96566e8", "type": "concept", "title": "Responsive adaptation"}, {"id": "9406a6b7-26a0-4614-96f5-8f6328c65caf", "type": "concept", "title": "Multiple page types"}, {"id": "ef9924dd-af27-44de-9b9d-fe22b7f3130d", "type": "concept", "title": "Consistency across a series"}], "description": "Gist: A good grid supports both order and surprise."}]}, {"id": "2c7f0a54-d18e-4cd3-9fdf-32f1dec69505", "type": "topic", "title": "Composition with Type", "description": "Treat type as form, image, texture, voice, and space within a designed composition.", "children": [{"id": "ec51ce42-bef7-4a3b-8668-8ab7c287c5b2", "type": "subtopic", "title": "Type as form", "children": [{"id": "f6919ae7-c700-4f75-91e9-8dc9907ee7b6", "type": "concept", "title": "Scale shifts"}, {"id": "a7a1d0d4-53af-405b-b842-c7b98b9e1b8e", "type": "concept", "title": "Crop and overlap"}, {"id": "bbe04cd6-4ff4-4038-b5cb-07dad8fe7ce0", "type": "concept", "title": "Typographic texture"}, {"id": "1d2989d3-7e9c-4088-8279-121f7feb03a9", "type": "concept", "title": "Negative space"}], "description": "Gist: Letters can function as shape, texture, mass, and movement as well as readable language."}, {"id": "a6932ceb-2272-4ad7-8484-af224be486f0", "type": "subtopic", "title": "Typographic image-making", "children": [{"id": "ef4cf101-1c6a-4938-8811-520518ba8da0", "type": "concept", "title": "Word-image relationships"}, {"id": "baf03f3a-4f60-47d2-85cd-a53bb1999d22", "type": "concept", "title": "Expressive typography"}, {"id": "10427e32-9fca-408f-b21b-577221ead695", "type": "concept", "title": "Figure-ground"}, {"id": "3212239e-c44f-49af-8141-8ab9b6382d93", "type": "concept", "title": "Poster studies"}], "description": "Gist: Compositions with type help students explore voice, metaphor, and visual impact."}, {"id": "9ac53c72-6ed9-4b5b-bc96-83ae93d5472a", "type": "subtopic", "title": "Space and balance", "children": [{"id": "c04efb96-3960-4589-b9d9-5cad66ff7bca", "type": "concept", "title": "White space"}, {"id": "c887c233-c445-43dd-b2ca-fbdfdcb3919d", "type": "concept", "title": "Asymmetry"}, {"id": "4537a2fa-0bb7-4f86-940b-6bc7514cbc35", "type": "concept", "title": "Tension and stability"}, {"id": "9e12fded-ad69-42f7-a962-f5248be06285", "type": "concept", "title": "Focal point"}], "description": "Gist: Composition teaches students to use silence and density as active design tools."}]}, {"id": "4b3193ae-b012-4ae5-8a43-6f2559b59226", "type": "topic", "title": "Reading, Legibility, and Readability", "description": "Design type for human reading conditions, including size, distance, medium, cognition, and context.", "children": [{"id": "757b869d-cbb7-4bf1-90bb-8031779b752f", "type": "subtopic", "title": "Legibility conditions", "children": [{"id": "5875d939-c396-440c-b4ae-e44e011d8a98", "type": "concept", "title": "Size"}, {"id": "e16974cf-f7ac-46bd-a241-0639cc911baf", "type": "concept", "title": "Contrast"}, {"id": "62346f13-1014-4dd0-b11c-5346af7e8c3a", "type": "concept", "title": "Typeface features"}, {"id": "c7595764-b0e3-41f8-aee6-80043067dc60", "type": "concept", "title": "Viewing distance"}], "description": "Gist: Legibility concerns whether individual letters and words can be recognized under real conditions."}, {"id": "7bb4c56e-8077-4b1b-84d3-ddf88762d6ae", "type": "subtopic", "title": "Readability over time", "children": [{"id": "d8ad90a6-e47c-457f-8175-3bf6c0929caf", "type": "concept", "title": "Paragraph style"}, {"id": "6fba2bce-9e51-45f3-bc2b-ad35dcaff7e2", "type": "concept", "title": "Line length"}, {"id": "c8971a0a-391d-4585-877f-06c5c2120ea7", "type": "concept", "title": "Leading"}, {"id": "9a9fa6ee-ff1a-4586-8fc6-fad93e9b75a9", "type": "concept", "title": "Hyphenation and justification"}], "description": "Gist: Readability concerns sustained reading comfort and comprehension."}, {"id": "1c3902fe-0375-461d-ae82-318cd90e49a6", "type": "subtopic", "title": "Testing with readers", "children": [{"id": "e255b635-0d11-424e-b7bb-6ac2a28103cd", "type": "concept", "title": "Print proofing"}, {"id": "ae05e891-32c3-47c1-a492-efc28194caa0", "type": "concept", "title": "Screen tests"}, {"id": "3ef3cc9c-0b01-473e-83c3-baf81e73e2dc", "type": "concept", "title": "Peer reading tests"}, {"id": "6a381539-1c28-4bf6-9130-89cb3cc663fe", "type": "concept", "title": "Iterative correction"}], "description": "Gist: Typography should be checked with the people, media, and contexts it is meant to serve."}]}, {"id": "f9a578b3-80de-42fe-bf69-8ecc5bb615da", "type": "topic", "title": "Typographic Voice and Tone", "description": "Use type choices to create personality, authority, intimacy, urgency, elegance, or play without losing clarity.", "children": [{"id": "5f43e884-e38d-4e4a-a2db-694ff3f6e116", "type": "subtopic", "title": "Voice through type choice", "children": [{"id": "93c615f3-2acf-4e5e-b1fe-d2de40a0b8fc", "type": "concept", "title": "Formal and informal voices"}, {"id": "75532d66-3852-4dc8-baca-66b923f81d12", "type": "concept", "title": "Warmth and authority"}, {"id": "09357fe0-1a39-455a-919d-1b941206a129", "type": "concept", "title": "Novelty and restraint"}, {"id": "42f322ef-4a6f-492b-b06e-629cb9f68d3d", "type": "concept", "title": "Brand fit"}], "description": "Gist: Typefaces carry mood, genre, and cultural signals that affect how words are received."}, {"id": "367799aa-56fe-450f-b3dc-8fe108cb285c", "type": "subtopic", "title": "Voice through composition", "children": [{"id": "64aa1665-00ad-43fb-a569-b4e3d5c497db", "type": "concept", "title": "Quiet layouts"}, {"id": "35581641-2850-4503-97f6-9bc22d696d83", "type": "concept", "title": "Bold display type"}, {"id": "d6e332db-213f-419b-94ff-2cf769372f6f", "type": "concept", "title": "Editorial tone"}, {"id": "e784eb75-e467-4398-b693-1c2fcb35df6b", "type": "concept", "title": "Experimental tone"}], "description": "Gist: Voice also emerges from scale, spacing, hierarchy, color, and composition."}, {"id": "e665f9c4-bec9-4efc-a27e-c778624d47d9", "type": "subtopic", "title": "Appropriateness and restraint", "children": [{"id": "0f647f4f-eb34-450d-a868-c85b9fc762c7", "type": "concept", "title": "Context fit"}, {"id": "7c8eff86-9edf-4c6c-aa0f-edbc5bc18a6d", "type": "concept", "title": "Avoiding novelty traps"}, {"id": "1ede43f1-007d-4ce3-9266-b0a6dab48da4", "type": "concept", "title": "Cultural sensitivity"}, {"id": "0f3bf11a-b517-4d05-bd62-f9d61066cd45", "type": "concept", "title": "Clarity under pressure"}], "description": "Gist: A strong typographic voice still has to serve content and readers."}]}, {"id": "e5648d32-0494-459f-a762-e66babb9b26f", "type": "topic", "title": "Typesetting Detail and Editorial Craft", "description": "Practice the small conventions that make paragraphs, captions, lists, punctuation, and documents feel finished.", "children": [{"id": "865c8c82-d880-4865-8303-02e94a0f57f4", "type": "subtopic", "title": "Paragraph craft", "children": [{"id": "77f69881-9dd1-411e-b8bd-6fc44430c8e3", "type": "concept", "title": "First-line indents"}, {"id": "267ab069-17aa-4acd-bee1-3766e1c16e76", "type": "concept", "title": "Space between paragraphs"}, {"id": "df723de7-dedf-4570-a7d6-4c84773a626f", "type": "concept", "title": "Widows and orphans"}, {"id": "65a4448b-e304-4bc5-824a-14dd4d70770f", "type": "concept", "title": "Rags"}], "description": "Gist: Professional typography lives in the details of paragraph construction and page rhythm."}, {"id": "a812be91-f42a-469b-8312-011ffb5a8ac7", "type": "subtopic", "title": "Punctuation and special characters", "children": [{"id": "b2cb7ad8-006e-4e3d-8c32-02f4a2f94873", "type": "concept", "title": "Curly quotes"}, {"id": "cee74220-8cec-428c-96d3-82bebf383a45", "type": "concept", "title": "Dashes"}, {"id": "87bcbc6a-e691-48ec-becb-16032c41b7e7", "type": "concept", "title": "Ellipses"}, {"id": "3475d28c-a129-4e7c-9c96-79923aad3d0b", "type": "concept", "title": "Apostrophes and primes"}], "description": "Gist: Typographic punctuation affects polish, readability, and professional credibility."}, {"id": "294f3c2b-49bd-4d9f-affb-b7e16f54577d", "type": "subtopic", "title": "Lists, captions, and notes", "children": [{"id": "3892396c-3156-4830-a3be-23eada1acd33", "type": "concept", "title": "Bulleted lists"}, {"id": "8ceb2264-ba40-4ea6-9be9-56116b54adb0", "type": "concept", "title": "Numbered lists"}, {"id": "d641cdcc-cd08-4c89-991a-3a95431257ac", "type": "concept", "title": "Captions"}, {"id": "6b701cde-6b08-496f-852a-b171ffdd6a9e", "type": "concept", "title": "Footnotes and credits"}], "description": "Gist: Supporting text often reveals whether a designer understands typographic systems."}]}, {"id": "76eddd88-09a4-4a47-903f-07e34a4c5a2a", "type": "topic", "title": "Type on Screen and Responsive Contexts", "description": "Introduce digital typography for web, mobile, variable screens, and changing viewport conditions.", "children": [{"id": "7d25457b-7444-4cbe-ad01-517256c470f5", "type": "subtopic", "title": "Screen rendering basics", "children": [{"id": "5dabfa83-9774-4c96-a5d1-68d0e353716a", "type": "concept", "title": "Font rendering"}, {"id": "3e11174c-9bc6-4bea-8530-d96d5401ecf9", "type": "concept", "title": "Web-safe fallbacks"}, {"id": "bfba4892-3cf5-4035-8b5e-10d7ae8b3ea3", "type": "concept", "title": "Hinting"}, {"id": "1b1fecce-ac35-4d79-8254-39b6542d8d56", "type": "concept", "title": "Resolution"}], "description": "Gist: Digital type changes across devices, operating systems, browsers, and pixel densities."}, {"id": "f48ee3c8-51e0-4419-b89d-aa50d31bc4de", "type": "subtopic", "title": "Responsive typography", "children": [{"id": "b82df416-85ec-40a8-a6ca-d83369ed04a9", "type": "concept", "title": "Fluid type scales"}, {"id": "0d42ab65-e348-4278-9096-f50b7ce29941", "type": "concept", "title": "Breakpoints"}, {"id": "c62689ff-0764-4870-906e-c34345ac0603", "type": "concept", "title": "Line length constraints"}, {"id": "c546239b-2d22-481d-9421-0e69d8edfe9f", "type": "concept", "title": "Mobile reading"}], "description": "Gist: Screen typography must adapt while preserving hierarchy and reading comfort."}, {"id": "71147a16-b4dd-4650-9bee-88b68e8fbc60", "type": "subtopic", "title": "Variable and web fonts", "children": [{"id": "81493c2c-5408-46e7-9353-d673c4f2dab3", "type": "concept", "title": "Variable axes"}, {"id": "01314649-2001-4c20-860a-74362e3b11b1", "type": "concept", "title": "Font loading"}, {"id": "fe7d8829-fba4-4830-bf67-aabb989aa0c0", "type": "concept", "title": "Performance"}, {"id": "9c9b8a1b-706e-47ae-b207-59ab024b8f51", "type": "concept", "title": "Licensing"}], "description": "Gist: Modern font technology gives designers more control and more responsibility."}]}, {"id": "5d2f6d55-1055-43f2-aaab-54b87818eedb", "type": "topic", "title": "Accessibility and Inclusive Typography", "description": "Design type that serves diverse readers across vision, language, disability, culture, and device constraints.", "children": [{"id": "88bfde01-9966-485b-a46c-df1b9d163ed6", "type": "subtopic", "title": "Accessible readability", "children": [{"id": "11bdac10-b07d-4187-ad4c-d802d625f2f2", "type": "concept", "title": "Contrast"}, {"id": "1a4b6e7c-8b19-4e23-9d05-ba8c293df4a3", "type": "concept", "title": "Minimum sizes"}, {"id": "2af2bbd3-6f22-4ac1-a223-e6fee902e951", "type": "concept", "title": "Line spacing"}, {"id": "a97883f8-db6a-4618-b25c-a3160ee3f20d", "type": "concept", "title": "Avoiding all-caps overuse"}], "description": "Gist: Inclusive typography starts with making text perceivable and usable by more readers."}, {"id": "a3dd07d1-bd1e-4ea2-a7c0-e78c415c956e", "type": "subtopic", "title": "Neurodiversity and cognitive load", "children": [{"id": "71e27265-a606-44a4-8759-819098b48ec7", "type": "concept", "title": "Clear hierarchy"}, {"id": "bc665b87-06ab-41b0-8d2d-da9fb4deefe4", "type": "concept", "title": "Plain structure"}, {"id": "7b571adf-1b26-4d61-b51a-38fddb0b0a18", "type": "concept", "title": "Predictable layouts"}, {"id": "23446f70-220f-4020-98f3-05fe951ba4f3", "type": "concept", "title": "Avoiding visual noise"}], "description": "Gist: Type choices can reduce or increase effort for readers with different processing needs."}, {"id": "a7842e0a-b753-4474-8fdd-6b389dc4e36d", "type": "subtopic", "title": "Multilingual and cultural considerations", "children": [{"id": "a041c3ed-768d-41ab-bc36-af2cd8f20649", "type": "concept", "title": "Diacritics"}, {"id": "9a8dfc83-52b7-4ba6-b733-2e9e51d80946", "type": "concept", "title": "Non-Latin scripts overview"}, {"id": "7efe0c98-3bba-4054-883b-e990490cb297", "type": "concept", "title": "Fallback fonts"}, {"id": "4fae0d28-cf6b-47b0-8942-717657270cb2", "type": "concept", "title": "Translation expansion"}], "description": "Gist: Typography must respect language systems, scripts, names, and cultural contexts."}]}, {"id": "07e27cef-4922-456a-8e76-71b57a516bbb", "type": "topic", "title": "Type Specimens, Research, and Precedent Analysis", "description": "Study real typographic work to build taste, vocabulary, research habits, and historical awareness.", "children": [{"id": "c6ceb261-f75b-4a86-8d4d-47699c3f29ac", "type": "subtopic", "title": "Typeface research", "children": [{"id": "37c014bb-7e3d-4ff0-84f3-9c24a73da481", "type": "concept", "title": "Designer and foundry"}, {"id": "aad80e2f-0b41-4ef9-a874-25ab0b615956", "type": "concept", "title": "Release context"}, {"id": "c3e8e92b-f0c1-4265-87db-4763462a4e03", "type": "concept", "title": "Intended use"}, {"id": "f2743c0e-e9ce-4ded-832e-524c2f9bc559", "type": "concept", "title": "Licensing"}], "description": "Gist: Research helps students understand what a typeface was designed to do and where it works well."}, {"id": "b3998be3-52b1-462d-b3c0-f154573c21fe", "type": "subtopic", "title": "Precedent analysis", "children": [{"id": "6c27cb9b-959b-4cd6-99d5-b7f85631e955", "type": "concept", "title": "Fonts In Use studies"}, {"id": "e7d7632e-e361-4465-b75c-caaa6039badb", "type": "concept", "title": "Editorial precedents"}, {"id": "d7b6f0e2-d4e9-4545-827b-416d59f30d7c", "type": "concept", "title": "Brand precedents"}, {"id": "cd0e7023-2b0c-4c9f-bef9-ef712732feab", "type": "concept", "title": "Historical specimens"}], "description": "Gist: Studying strong work builds judgment about hierarchy, pairing, spacing, and voice."}, {"id": "21ce5cc8-10ee-41f5-86ee-b369b2f1f569", "type": "subtopic", "title": "Specimen design", "children": [{"id": "57796b4f-7839-4e08-b7da-61ea8ee13207", "type": "concept", "title": "Character set"}, {"id": "fd987f9a-79ae-4c87-95a8-137ecf3a0f9c", "type": "concept", "title": "Text settings"}, {"id": "42444f1c-1910-4011-8958-08346e821d27", "type": "concept", "title": "Display settings"}, {"id": "295e97fb-00d6-4f63-849b-dba31a4fedab", "type": "concept", "title": "Use-case demonstrations"}], "description": "Gist: A specimen teaches students to reveal a typeface's structure, range, and personality."}]}, {"id": "132eb60c-3acd-45c9-a6a0-41821f70de23", "type": "topic", "title": "Typographic Critique, Revision, and Rationale", "description": "Develop the studio language and process habits needed to critique, defend, and improve typographic choices.", "children": [{"id": "87077350-c9eb-43ff-8c84-d34fafd69598", "type": "subtopic", "title": "Critique vocabulary", "children": [{"id": "1cc97b92-0875-4046-868f-fe373c33d283", "type": "concept", "title": "Hierarchy"}, {"id": "40648f5e-86c6-4550-b244-9d45127b7e72", "type": "concept", "title": "Legibility"}, {"id": "1cea7375-e57a-4c62-b179-d240982eec05", "type": "concept", "title": "Alignment"}, {"id": "fdb979fb-1491-4aff-843f-dc7b293caec3", "type": "concept", "title": "Typographic color"}], "description": "Gist: Students need precise language to discuss typographic choices beyond liking or disliking them."}, {"id": "a880d815-72fa-4f5b-b8ff-187c319c07d9", "type": "subtopic", "title": "Revision workflow", "children": [{"id": "d96e87a7-e35f-45b0-9792-6d94c42fd6c6", "type": "concept", "title": "Print proofs"}, {"id": "1cc1c4e1-e855-4f3d-bc66-bfd8a9902fd3", "type": "concept", "title": "Annotated drafts"}, {"id": "0455694e-ca46-43b4-a260-679aa6ecf5f8", "type": "concept", "title": "Peer feedback"}, {"id": "5ecbaf83-d895-4854-8b65-04d24fc71353", "type": "concept", "title": "Version comparison"}], "description": "Gist: Typographic revision is a sequence of tests, proofs, comparisons, and refinements."}, {"id": "558e0531-52c3-4a97-8d08-71da24d708b3", "type": "subtopic", "title": "Rationale writing", "children": [{"id": "08848ac3-b81a-4631-94f6-557debb57012", "type": "concept", "title": "Decision statements"}, {"id": "a7c4f637-62fd-4664-bb3e-c3153ecfe2f7", "type": "concept", "title": "Evidence from testing"}, {"id": "df6e511e-ded3-4498-a49b-6abf77c891c7", "type": "concept", "title": "Tradeoffs"}, {"id": "6596d73e-d079-4005-a606-38e2e56a4fa9", "type": "concept", "title": "Presentation language"}], "description": "Gist: Designers must explain how choices serve content, audience, medium, and goals."}]}, {"id": "6c529bf7-8c5d-4b17-b55f-5da754fcd731", "type": "topic", "title": "Final Portfolio Project: Typographic System", "description": "Synthesize anatomy, history, hierarchy, spacing, grids, voice, and accessibility in a polished typographic system.", "children": [{"id": "3966e715-a167-403a-8100-0d6b722bca10", "type": "subtopic", "title": "Project brief", "children": [{"id": "a8d37f4f-fcde-4dd2-b192-a98215035167", "type": "concept", "title": "Audience"}, {"id": "a831d037-4c66-4fcd-ba9c-4f64e3579e0b", "type": "concept", "title": "Message"}, {"id": "62db8102-6872-4543-8f1f-714e1b045c63", "type": "concept", "title": "Mediums"}, {"id": "a5b67d3d-9d3a-4312-bbc3-afd0caf6a838", "type": "concept", "title": "Constraints"}], "description": "Gist: The final project asks students to define a communication problem and design a coherent typographic response."}, {"id": "2ea16bc3-7808-43d2-8990-942e6a4a5d1e", "type": "subtopic", "title": "System development", "children": [{"id": "aa887e8a-3624-4a46-b429-870b7e15d4c4", "type": "concept", "title": "Type palette"}, {"id": "0ffe963c-a658-43e9-84f1-45beed6bf614", "type": "concept", "title": "Grid rules"}, {"id": "79f05faa-cd8b-4952-b182-bf0156fe329b", "type": "concept", "title": "Hierarchy rules"}, {"id": "f6eabd39-0529-4f40-bde0-fa3baf35df1d", "type": "concept", "title": "Use-case variations"}], "description": "Gist: A typographic system shows consistency across multiple formats, not just one attractive layout."}, {"id": "64479851-98b3-421d-a034-7d33eab82eb3", "type": "subtopic", "title": "Final presentation", "children": [{"id": "2507a523-72bc-476b-86c3-39e7a895c1c9", "type": "concept", "title": "Final artifacts"}, {"id": "425fa69c-b84c-4288-9588-4f032c78f8b1", "type": "concept", "title": "Process archive"}, {"id": "cae8e378-def2-4d2d-8532-eeb7e6a40f55", "type": "concept", "title": "Critique response"}, {"id": "66555702-04f5-4f17-b108-59368d8078cc", "type": "concept", "title": "Portfolio captions"}], "description": "Gist: Portfolio-ready typography requires craft, documentation, and clear explanation."}]}], "dbBacked": true}$typ1json$::jsonb,
