update public.learning_paths
set
  title = 'Typography I',
  goal = 'Typography I',
  summary = 'Typography I treats typography as a system for making language visible, expressive, organized, and useful. Students study letterform anatomy, classification and history, type families and selection, spacing and rhythm, hierarchy, grids, composition, legibility, voice, editorial typesetting, screen and responsive type, inclusive practice, specimens, critique, and a final typographic system.',
  data = $typ1json${"slug": "typography-i", "title": "Typography I", "description": "Typography I treats typography as a system for making language visible, expressive, organized, and useful. Students study letterform anatomy, classification and history, type families and selection, spacing and rhythm, hierarchy, grids, composition, legibility, voice, editorial typesetting, screen and responsive type, inclusive practice, specimens, critique, and a final typographic system.", "topics": [{"id": "bc5a3f60-83b0-4ecd-a821-535fb9e3c263", "type": "topic", "title": "Typography as Visual Language", "description": "Understand typography as a system for making language visible, expressive, organized, and useful.", "children": [{"id": "dfe2a63b-8171-413f-b153-2387afa28b72", "type": "subtopic", "title": "Visible language", "children": [{"id": "6e9bbb2d-462e-4254-b09d-cdeff073b530", "type": "concept", "title": "Form and meaning"}, {"id": "74bf9515-f4d7-4882-bab6-52599499f7ce", "type": "concept", "title": "Tone and connotation"}, {"id": "582d8691-9ecb-46d5-88c2-eeb991107eb9", "type": "concept", "title": "Type as image"}, {"id": "0d9046b8-16b7-4b22-b07c-4f6b93740a2b", "type": "concept", "title": "Type as interface"}], "description": "Gist: Typography begins with the idea that words have visual form before they are read as language."}, {"id": "f23ffcfb-d23f-4166-97dc-7fb215e2cb90", "type": "subtopic", "title": "Typographic responsibility", "children": [{"id": "b2e2f6c5-6bb2-4a8d-8557-aae3c8b15a50", "type": "concept", "title": "Reader needs"}, {"id": "1705f85a-977b-412b-9595-2cdacfdc575a", "type": "concept", "title": "Context of use"}, {"id": "7acb765e-6c28-4367-a74b-5fad65895402", "type": "concept", "title": "Authority and credibility"}, {"id": "0d77058e-cef8-4294-acc1-893d9c2a3e86", "type": "concept", "title": "Ethical presentation"}], "description": "Gist: Designers make choices that affect comprehension, trust, access, and cultural meaning."}, {"id": "74aad7e8-79bc-4d7b-bbd0-c918